"""SMT-based solving and optimization experiments built on Z3."""

from __future__ import annotations

from z3 import Distinct, If, Int, Optimize, Or, Solver, sat

from framework import PETERSEN_GRAPH, report_result


def count_nqueens_solutions(n: int) -> int:
    """Count all N-Queens solutions using model blocking."""
    solver = Solver()
    queens = [Int(f"q_{row}") for row in range(n)]

    for queen in queens:
        solver.add(queen >= 0, queen < n)

    solver.add(Distinct(*queens))
    for i in range(n):
        for j in range(i + 1, n):
            distance = j - i
            solver.add(queens[i] - queens[j] != distance)
            solver.add(queens[i] - queens[j] != -distance)

    count = 0
    while solver.check() == sat:
        model = solver.model()
        assignment = [model.eval(queen).as_long() for queen in queens]
        solver.add(Or(*[queen != value for queen, value in zip(queens, assignment)]))
        count += 1
    return count


def chromatic_number(graph) -> int:
    """Return the minimum number of colors needed to color the graph."""
    for num_colors in range(1, graph.num_nodes() + 1):
        solver = Solver()
        colors = {node: Int(f"color_{node}") for node in graph.nodes}
        for color in colors.values():
            solver.add(color >= 0, color < num_colors)
        for left, right in graph.edges:
            solver.add(colors[left] != colors[right])
        if solver.check() == sat:
            return num_colors
    raise ValueError("graph coloring unexpectedly unsatisfiable")


def schedule_jobs(jobs, num_machines: int) -> int:
    """Schedule jobs on identical machines while minimizing makespan."""
    optimizer = Optimize()

    starts = {job_id: Int(f"start_{job_id}") for job_id, _ in jobs}
    ends = {job_id: Int(f"end_{job_id}") for job_id, _ in jobs}
    machines = {job_id: Int(f"machine_{job_id}") for job_id, _ in jobs}
    durations = dict(jobs)

    for job_id, duration in jobs:
        optimizer.add(starts[job_id] >= 0)
        optimizer.add(ends[job_id] == starts[job_id] + duration)
        optimizer.add(machines[job_id] >= 0, machines[job_id] < num_machines)

    for i, (left_job, _) in enumerate(jobs):
        for right_job, _ in jobs[i + 1 :]:
            optimizer.add(
                Or(
                    machines[left_job] != machines[right_job],
                    ends[left_job] <= starts[right_job],
                    ends[right_job] <= starts[left_job],
                )
            )

    makespan = Int("makespan")
    for job_id in durations:
        optimizer.add(makespan >= ends[job_id])
    optimizer.minimize(makespan)

    if optimizer.check() != sat:
        raise ValueError("job scheduling instance is unsatisfiable")

    model = optimizer.model()
    return model.eval(makespan).as_long()


def run_z3_experiments() -> dict[str, int]:
    """Run all SMT experiments and report their metrics."""
    jobs = [("A", 3), ("B", 5), ("C", 2), ("D", 4), ("E", 6), ("F", 1)]
    results = {
        "Z3_NQUEENS_8_SOLUTIONS": count_nqueens_solutions(8),
        "Z3_PETERSEN_CHROMATIC": chromatic_number(PETERSEN_GRAPH),
        "Z3_SCHEDULE_MAKESPAN": schedule_jobs(jobs, 3),
    }
    for key, value in results.items():
        report_result(key, value)
    return results


if __name__ == "__main__":
    run_z3_experiments()

