"""Experiments for the imperative-to-Horn translator."""

from __future__ import annotations

import time

from framework import report_result
from verification.horn_translator import HornEncoder, parse_program, verify_program


PROGRAMS = {
    "simple_counter": """
        var x = 0;
        while (x < 10) {
            x = x + 1;
        }
        assert(x == 10);
    """,
    "sum_accumulator": """
        var s = 0;
        var i = 0;
        while (i < 5) {
            s = s + i;
            i = i + 1;
        }
        assert(s >= 0);
    """,
    "branch_test": """
        var x = 5;
        if (x > 3) {
            x = x - 1;
        } else {
            x = x + 1;
        }
        assert(x >= 0);
    """,
    "unsafe_loop": """
        var x = 0;
        while (x < 100) {
            x = x + 2;
        }
        assert(x < 50);
    """,
    "nested_arithmetic": """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6);
    """,
}


def run_horn_translator_experiments():
    """Translate and verify the five required benchmark programs."""
    translation_start = time.perf_counter()
    translation_data = []
    for source in PROGRAMS.values():
        ast = parse_program(source)
        encoder = HornEncoder()
        clauses = encoder.encode_program(ast)
        translation_data.append((len(clauses), len(encoder.relations)))
    translation_time = time.perf_counter() - translation_start

    verification_results = [verify_program(source) for source in PROGRAMS.values()]
    results = {
        "HORN_CLAUSES_GENERATED": sum(item[0] for item in translation_data),
        "HORN_PROGRAMS_VERIFIED": sum(1 for item in verification_results if item["safe"]),
        "HORN_PROGRAMS_UNSAFE": sum(1 for item in verification_results if not item["safe"]),
        "HORN_LOOP_INVARIANTS": sum(item["loop_invariants"] for item in verification_results),
        "HORN_TRANSLATION_TIME": f"{translation_time:.2f}",
    }
    for key, value in results.items():
        report_result(key, value)
    return results


if __name__ == "__main__":
    run_horn_translator_experiments()

