"""Imperative-to-Horn translation and verification utilities."""

from __future__ import annotations

from dataclasses import dataclass, field
import re
from typing import Iterable

import z3


@dataclass(frozen=True)
class Variable:
    name: str


@dataclass(frozen=True)
class Const:
    value: int | bool


@dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: object


@dataclass(frozen=True)
class BinOp:
    op: str
    left: object
    right: object


@dataclass(frozen=True)
class Assign:
    var_name: str
    expr: object


@dataclass(frozen=True)
class If:
    cond: object
    then_body: "Sequence"
    else_body: "Sequence"


@dataclass(frozen=True)
class While:
    cond: object
    body: "Sequence"
    bound: int | None = None


@dataclass(frozen=True)
class Assert:
    cond: object


@dataclass(frozen=True)
class Sequence:
    stmts: list[object] = field(default_factory=list)


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    position: int


@dataclass
class HornClause:
    head: z3.BoolRef
    body: list[z3.BoolRef]
    description: str = ""


TOKEN_REGEX = re.compile(
    r"""
    (?P<SPACE>\s+)
  | (?P<COMMENT>//[^\n]*)
  | (?P<NUMBER>\d+)
  | (?P<LE><=)
  | (?P<GE>>=)
  | (?P<EQ>==)
  | (?P<NE>!=)
  | (?P<AND2>&&)
  | (?P<OR2>\|\|)
  | (?P<NOT2>!)
  | (?P<IDENT>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<SYMBOL>[{}()\[\];=,+\-*<>])
    """,
    re.VERBOSE,
)


KEYWORDS = {"var", "if", "else", "while", "assert", "and", "or", "not", "true", "false", "bound"}


def tokenize(text: str) -> list[Token]:
    """Tokenize the input program text."""
    tokens: list[Token] = []
    index = 0
    while index < len(text):
        match = TOKEN_REGEX.match(text, index)
        if match is None:
            raise SyntaxError(f"Unexpected character at position {index}: {text[index]!r}")
        kind = match.lastgroup
        value = match.group()
        if kind not in {"SPACE", "COMMENT"}:
            if kind == "IDENT" and value in KEYWORDS:
                kind = value.upper()
            tokens.append(Token(kind, value, index))
        index = match.end()
    tokens.append(Token("EOF", "", len(text)))
    return tokens


class Parser:
    """Recursive-descent parser for the simple imperative language."""

    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.index = 0

    def current(self) -> Token:
        return self.tokens[self.index]

    def accept(self, *kinds: str) -> Token | None:
        if self.current().kind in kinds:
            token = self.current()
            self.index += 1
            return token
        return None

    def expect(self, kind: str, value: str | None = None) -> Token:
        token = self.current()
        if token.kind != kind:
            raise SyntaxError(f"Expected {kind}, got {token.kind} at position {token.position}")
        if value is not None and token.value != value:
            raise SyntaxError(f"Expected {value!r}, got {token.value!r} at position {token.position}")
        self.index += 1
        return token

    def parse_program(self) -> Sequence:
        statements = []
        while self.current().kind != "EOF":
            statements.append(self.parse_statement())
        return Sequence(statements)

    def parse_statement(self):
        token = self.current()
        if token.kind == "VAR":
            self.expect("VAR")
            name = self.expect("IDENT").value
            self.expect("SYMBOL", "=")
            expr = self.parse_expr()
            self.expect("SYMBOL", ";")
            return Assign(name, expr)
        if token.kind == "IF":
            self.expect("IF")
            cond = self.parse_paren_expr()
            then_body = self.parse_block()
            else_body = Sequence([])
            if self.accept("ELSE"):
                else_body = self.parse_block()
            return If(cond, then_body, else_body)
        if token.kind == "WHILE":
            self.expect("WHILE")
            bound = self.parse_optional_bound()
            cond = self.parse_paren_expr()
            if bound is None:
                bound = self.parse_optional_bound()
            body = self.parse_block()
            return While(cond, body, bound)
        if token.kind == "ASSERT":
            self.expect("ASSERT")
            cond = self.parse_paren_expr()
            self.expect("SYMBOL", ";")
            return Assert(cond)
        name = self.expect("IDENT").value
        self.expect("SYMBOL", "=")
        expr = self.parse_expr()
        self.expect("SYMBOL", ";")
        return Assign(name, expr)

    def parse_block(self) -> Sequence:
        self.expect("SYMBOL", "{")
        statements = []
        while not (self.current().kind == "SYMBOL" and self.current().value == "}"):
            statements.append(self.parse_statement())
        self.expect("SYMBOL", "}")
        return Sequence(statements)

    def parse_optional_bound(self) -> int | None:
        if not self.accept("SYMBOL") or self.tokens[self.index - 1].value != "[":
            return None
        if self.current().kind == "BOUND":
            self.expect("BOUND")
            if self.current().kind == "SYMBOL" and self.current().value == "=":
                self.expect("SYMBOL", "=")
        value = int(self.expect("NUMBER").value)
        self.expect("SYMBOL", "]")
        return value

    def parse_paren_expr(self):
        self.expect("SYMBOL", "(")
        expr = self.parse_expr()
        self.expect("SYMBOL", ")")
        return expr

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        expr = self.parse_and()
        while self.current().kind in {"OR", "OR2"}:
            self.index += 1
            expr = BinOp("or", expr, self.parse_and())
        return expr

    def parse_and(self):
        expr = self.parse_not()
        while self.current().kind in {"AND", "AND2"}:
            self.index += 1
            expr = BinOp("and", expr, self.parse_not())
        return expr

    def parse_not(self):
        if self.current().kind in {"NOT", "NOT2"}:
            self.index += 1
            return UnaryOp("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        expr = self.parse_additive()
        while self.current().kind in {"LE", "GE", "EQ", "NE"} or (
            self.current().kind == "SYMBOL" and self.current().value in {"<", ">"}
        ):
            token = self.current()
            self.index += 1
            expr = BinOp(token.value, expr, self.parse_additive())
        return expr

    def parse_additive(self):
        expr = self.parse_term()
        while self.current().kind == "SYMBOL" and self.current().value in {"+", "-"}:
            op = self.current().value
            self.index += 1
            expr = BinOp(op, expr, self.parse_term())
        return expr

    def parse_term(self):
        expr = self.parse_factor()
        while self.current().kind == "SYMBOL" and self.current().value == "*":
            self.expect("SYMBOL", "*")
            expr = BinOp("*", expr, self.parse_factor())
        return expr

    def parse_factor(self):
        token = self.current()
        if token.kind == "NUMBER":
            self.index += 1
            return Const(int(token.value))
        if token.kind == "TRUE":
            self.index += 1
            return Const(True)
        if token.kind == "FALSE":
            self.index += 1
            return Const(False)
        if token.kind == "IDENT":
            self.index += 1
            return Variable(token.value)
        if token.kind == "SYMBOL" and token.value == "(":
            return self.parse_paren_expr()
        if token.kind == "SYMBOL" and token.value == "-":
            self.expect("SYMBOL", "-")
            return BinOp("-", Const(0), self.parse_factor())
        raise SyntaxError(f"Unexpected token {token.kind} at position {token.position}")


def parse_program(text: str) -> Sequence:
    """Parse a program string into a Sequence AST."""
    parser = Parser(tokenize(text))
    return parser.parse_program()


def _iter_expr_vars(expr) -> Iterable[str]:
    if isinstance(expr, Variable):
        yield expr.name
    elif isinstance(expr, BinOp):
        yield from _iter_expr_vars(expr.left)
        yield from _iter_expr_vars(expr.right)
    elif isinstance(expr, UnaryOp):
        yield from _iter_expr_vars(expr.operand)


def _collect_variables(stmt, names: set[str]):
    if isinstance(stmt, Assign):
        names.add(stmt.var_name)
        names.update(_iter_expr_vars(stmt.expr))
    elif isinstance(stmt, Assert):
        names.update(_iter_expr_vars(stmt.cond))
    elif isinstance(stmt, If):
        names.update(_iter_expr_vars(stmt.cond))
        for nested in stmt.then_body.stmts:
            _collect_variables(nested, names)
        for nested in stmt.else_body.stmts:
            _collect_variables(nested, names)
    elif isinstance(stmt, While):
        names.update(_iter_expr_vars(stmt.cond))
        for nested in stmt.body.stmts:
            _collect_variables(nested, names)
    elif isinstance(stmt, Sequence):
        for nested in stmt.stmts:
            _collect_variables(nested, names)


class HornEncoder:
    """Encode parsed programs into Spacer-compatible Horn clauses."""

    def __init__(self):
        self.program_vars: list[str] = []
        self.state_sorts: list[z3.SortRef] = []
        self.relations: dict[str, z3.FuncDeclRef] = {}
        self.clauses: list[HornClause] = []
        self._fresh_index = 0
        self._declared_vars: dict[str, z3.ExprRef] = {}
        self.error_rel: z3.FuncDeclRef | None = None
        self.exit_relation: z3.FuncDeclRef | None = None
        self.loop_relations: list[str] = []
        self.loop_count = 0

    def encode_program(self, ast: Sequence) -> list[HornClause]:
        """Traverse the AST and populate the Horn clause list."""
        names: set[str] = set()
        _collect_variables(ast, names)
        self.program_vars = sorted(names)
        self.state_sorts = [z3.IntSort() for _ in self.program_vars]
        self.relations = {}
        self.clauses = []
        self._fresh_index = 0
        self._declared_vars = {}
        self.loop_relations = []
        self.loop_count = 0
        self.error_rel = self._relation("error", arity=0)
        entry_rel = self._relation("entry")
        self.exit_relation = self._relation("exit")

        entry_state = self._fresh_state("entry")
        self.clauses.append(
            HornClause(
                head=entry_rel(*entry_state),
                body=[],
                description="Program entry relation is unconstrained.",
            )
        )
        self._encode_stmt(ast, entry_rel, self.exit_relation)
        return self.clauses

    def encode_assignment(self, assign: Assign, pre_rel, post_rel):
        """Encode a state-transforming assignment clause."""
        pre_state = self._fresh_state("assign_pre")
        post_state = self._fresh_state("assign_post")
        pre_env = self._env(pre_state)
        post_env = self._env(post_state)
        constraints = [post_env[assign.var_name] == self._expr_to_z3(assign.expr, pre_env)]
        constraints.extend(
            post_env[name] == pre_env[name] for name in self.program_vars if name != assign.var_name
        )
        self.clauses.append(
            HornClause(
                head=post_rel(*post_state),
                body=[pre_rel(*pre_state), *constraints],
                description=f"Assign {assign.var_name}.",
            )
        )

    def encode_branch(self, if_node: If, pre_rel, post_rel):
        """Encode a conditional branch using split entry relations."""
        then_rel = self._relation("if_then")
        else_rel = self._relation("if_else")
        pre_state = self._fresh_state("if_state")
        pre_env = self._env(pre_state)
        cond = self._expr_to_z3(if_node.cond, pre_env)

        self.clauses.append(
            HornClause(
                head=then_rel(*pre_state),
                body=[pre_rel(*pre_state), cond],
                description="If-then branch gate.",
            )
        )
        self.clauses.append(
            HornClause(
                head=else_rel(*pre_state),
                body=[pre_rel(*pre_state), z3.Not(cond)],
                description="If-else branch gate.",
            )
        )
        self._encode_stmt(if_node.then_body, then_rel, post_rel)
        self._encode_stmt(if_node.else_body, else_rel, post_rel)

    def encode_loop(self, while_node: While, pre_rel, post_rel):
        """Encode an unbounded loop recursively or unroll it when bounded."""
        if while_node.bound is not None:
            self._encode_bounded_loop(while_node, pre_rel, post_rel)
            return

        loop_rel = self._relation("loop")
        self.loop_relations.append(loop_rel.name())
        self.loop_count += 1
        body_entry = self._relation("loop_body")
        body_exit = self._relation("loop_body_exit")

        entry_state = self._fresh_state("loop_entry")
        self.clauses.append(
            HornClause(
                head=loop_rel(*entry_state),
                body=[pre_rel(*entry_state)],
                description="Loop entry.",
            )
        )

        test_state = self._fresh_state("loop_test")
        test_env = self._env(test_state)
        cond = self._expr_to_z3(while_node.cond, test_env)
        self.clauses.append(
            HornClause(
                head=body_entry(*test_state),
                body=[loop_rel(*test_state), cond],
                description="Loop body when the guard holds.",
            )
        )
        self.clauses.append(
            HornClause(
                head=post_rel(*test_state),
                body=[loop_rel(*test_state), z3.Not(cond)],
                description="Loop exit when the guard fails.",
            )
        )

        self._encode_stmt(while_node.body, body_entry, body_exit)
        body_state = self._fresh_state("loop_back")
        self.clauses.append(
            HornClause(
                head=loop_rel(*body_state),
                body=[body_exit(*body_state)],
                description="Loop back-edge.",
            )
        )

    def encode_assertion(self, assert_node: Assert, pre_rel, post_rel=None):
        """Encode an assertion failure query and optional success passthrough."""
        pre_state = self._fresh_state("assert_state")
        pre_env = self._env(pre_state)
        cond = self._expr_to_z3(assert_node.cond, pre_env)
        self.clauses.append(
            HornClause(
                head=self.error_rel(),
                body=[pre_rel(*pre_state), z3.Not(cond)],
                description="Assertion violation reaches Error.",
            )
        )
        if post_rel is not None:
            self.clauses.append(
                HornClause(
                    head=post_rel(*pre_state),
                    body=[pre_rel(*pre_state), cond],
                    description="Assertion success preserves state.",
                )
            )

    def to_z3(self, program_vars=None):
        """Convert the encoded clauses into a Z3 Fixedpoint context."""
        if program_vars is not None:
            self.program_vars = list(program_vars)
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        fp.register_relation(*self.relations.values())
        fp.declare_var(*self._declared_vars.values())
        for clause in self.clauses:
            if clause.body:
                fp.rule(clause.head, clause.body)
            else:
                fp.rule(clause.head, z3.BoolVal(True))
        return fp, self.error_rel()

    def _encode_stmt(self, stmt, pre_rel, post_rel):
        if isinstance(stmt, Sequence):
            if not stmt.stmts:
                self._encode_skip(pre_rel, post_rel)
                return
            current_rel = pre_rel
            for index, nested in enumerate(stmt.stmts):
                target_rel = post_rel if index == len(stmt.stmts) - 1 else self._relation("seq")
                self._encode_stmt(nested, current_rel, target_rel)
                current_rel = target_rel
            return
        if isinstance(stmt, Assign):
            self.encode_assignment(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, If):
            self.encode_branch(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, While):
            self.encode_loop(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, Assert):
            self.encode_assertion(stmt, pre_rel, post_rel)
            return
        raise TypeError(f"Unsupported statement type: {type(stmt)!r}")

    def _encode_bounded_loop(self, while_node: While, pre_rel, post_rel):
        active_rel = pre_rel
        bound = while_node.bound or 0
        for _ in range(bound):
            body_rel = self._relation("bounded_loop_body")
            next_rel = self._relation("bounded_loop_next")
            test_state = self._fresh_state("bounded_loop_test")
            test_env = self._env(test_state)
            cond = self._expr_to_z3(while_node.cond, test_env)
            self.clauses.append(
                HornClause(
                    head=body_rel(*test_state),
                    body=[active_rel(*test_state), cond],
                    description="Bounded loop body gate.",
                )
            )
            self.clauses.append(
                HornClause(
                    head=post_rel(*test_state),
                    body=[active_rel(*test_state), z3.Not(cond)],
                    description="Bounded loop early exit.",
                )
            )
            self._encode_stmt(while_node.body, body_rel, next_rel)
            active_rel = next_rel
        self._encode_skip(active_rel, post_rel)

    def _encode_skip(self, pre_rel, post_rel):
        state = self._fresh_state("skip")
        self.clauses.append(
            HornClause(
                head=post_rel(*state),
                body=[pre_rel(*state)],
                description="Skip/passthrough.",
            )
        )

    def _relation(self, prefix: str, arity: int | None = None):
        relation_name = f"{prefix}_{len(self.relations)}"
        relation_arity = len(self.state_sorts) if arity is None else arity
        relation = z3.Function(
            relation_name,
            *([z3.IntSort()] * relation_arity),
            z3.BoolSort(),
        )
        self.relations[relation_name] = relation
        return relation

    def _fresh_state(self, prefix: str):
        state = []
        for name in self.program_vars:
            symbol = z3.Int(f"{name}_{prefix}_{self._fresh_index}")
            self._declared_vars[str(symbol)] = symbol
            state.append(symbol)
        self._fresh_index += 1
        return state

    def _env(self, state) -> dict[str, z3.ArithRef]:
        return dict(zip(self.program_vars, state))

    def _expr_to_z3(self, expr, env):
        if isinstance(expr, Const):
            if isinstance(expr.value, bool):
                return z3.BoolVal(expr.value)
            return z3.IntVal(expr.value)
        if isinstance(expr, Variable):
            return env[expr.name]
        if isinstance(expr, UnaryOp):
            operand = self._expr_to_z3(expr.operand, env)
            if expr.op == "not":
                return z3.Not(operand)
            raise ValueError(f"Unsupported unary operator: {expr.op}")
        if isinstance(expr, BinOp):
            left = self._expr_to_z3(expr.left, env)
            right = self._expr_to_z3(expr.right, env)
            if expr.op == "+":
                return left + right
            if expr.op == "-":
                return left - right
            if expr.op == "*":
                return left * right
            if expr.op == "<":
                return left < right
            if expr.op == "<=":
                return left <= right
            if expr.op == "==":
                return left == right
            if expr.op == "!=":
                return left != right
            if expr.op == ">":
                return left > right
            if expr.op == ">=":
                return left >= right
            if expr.op == "and":
                return z3.And(left, right)
            if expr.op == "or":
                return z3.Or(left, right)
        raise ValueError(f"Unsupported expression: {expr!r}")


def verify_program(text: str):
    """Parse, encode, and verify a program with Spacer."""
    ast = parse_program(text)
    encoder = HornEncoder()
    clauses = encoder.encode_program(ast)
    fp, error_query = encoder.to_z3(encoder.program_vars)
    result = fp.query(error_query)
    answer = str(fp.get_answer())
    invariant_count = len(encoder.loop_relations) if result == z3.unsat and answer else 0
    return {
        "safe": result == z3.unsat,
        "num_clauses": len(clauses),
        "num_relations": len(encoder.relations),
        "invariant": answer if result == z3.unsat else None,
        "loop_invariants": invariant_count,
    }

