TOKEN_REGEX = re.compile(
    r"""
    (?P<SPACE>\s+)
  | (?P<COMMENT>//[^\n]*)
  | (?P<NUMBER>\d+)
  | (?P<LE><=)
  | (?P<GE>>=)
  | (?P<EQ>==)
  | (?P<NE>!=)
  | (?P<AND2>&&)
  | (?P<OR2>\|\|)
  | (?P<NOT2>!)
  | (?P<IDENT>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<SYMBOL>[{}()\[\];=,+\-*<>])
    """,
    re.VERBOSE,
)


KEYWORDS = {"var", "if", "else", "while", "assert", "and", "or", "not", "true", "false", "bound"}


def tokenize(text: str) -> list[Token]:
    """Tokenize the input program text."""
    tokens: list[Token] = []
    index = 0
    while index < len(text):
        match = TOKEN_REGEX.match(text, index)
        if match is None:
            raise SyntaxError(f"Unexpected character at position {index}: {text[index]!r}")
        kind = match.lastgroup
        value = match.group()
        if kind not in {"SPACE", "COMMENT"}:
            if kind == "IDENT" and value in KEYWORDS:
                kind = value.upper()
            tokens.append(Token(kind, value, index))
        index = match.end()
    tokens.append(Token("EOF", "", len(text)))
    return tokens


