            raise SyntaxError(f"Expected {kind}, got {token.kind} at position {token.position}")
        if value is not None and token.value != value:
            raise SyntaxError(f"Expected {value!r}, got {token.value!r} at position {token.position}")
        self.index += 1
        return token

    def parse_program(self) -> Sequence:
