            self.current().kind == "SYMBOL" and self.current().value in {"<", ">"}
        ):
            token = self.current()
            self.index += 1
            expr = BinOp(token.value, expr, self.parse_additive())
        return expr

    def parse_additive(self):
        expr = self.parse_term()
        while self.current().kind == "SYMBOL" and self.current().value in {"+", "-"}:
            op = self.current().value
            self.index += 1
            expr = BinOp(op, expr, self.parse_term())
        return expr

