def parse_program(text: str) -> Sequence:
    """Parse a program string into a Sequence AST."""
    parser = Parser(tokenize(text))
    return parser.parse_program()


def _iter_expr_vars(expr) -> Iterable[str]:
    if isinstance(expr, Variable):
        yield expr.name
    elif isinstance(expr, BinOp):
        yield from _iter_expr_vars(expr.left)
        yield from _iter_expr_vars(expr.right)
    elif isinstance(expr, UnaryOp):
        yield from _iter_expr_vars(expr.operand)


def _collect_variables(stmt, names: set[str]):
    if isinstance(stmt, Assign):
        names.add(stmt.var_name)
        names.update(_iter_expr_vars(stmt.expr))
    elif isinstance(stmt, Assert):
        names.update(_iter_expr_vars(stmt.cond))
    elif isinstance(stmt, If):
        names.update(_iter_expr_vars(stmt.cond))
        for nested in stmt.then_body.stmts:
            _collect_variables(nested, names)
        for nested in stmt.else_body.stmts:
            _collect_variables(nested, names)
    elif isinstance(stmt, While):
        names.update(_iter_expr_vars(stmt.cond))
        for nested in stmt.body.stmts:
            _collect_variables(nested, names)
    elif isinstance(stmt, Sequence):
        for nested in stmt.stmts:
            _collect_variables(nested, names)


