                head=entry_rel(*entry_state),
                body=[],
                description="Program entry relation is unconstrained.",
            )
        )
        self._encode_stmt(ast, entry_rel, self.exit_relation)
        return self.clauses

    def encode_assignment(self, assign: Assign, pre_rel, post_rel):
        """Encode a state-transforming assignment clause."""
        pre_state = self._fresh_state("assign_pre")
        post_state = self._fresh_state("assign_post")
        pre_env = self._env(pre_state)
        post_env = self._env(post_state)
        constraints = [post_env[assign.var_name] == self._expr_to_z3(assign.expr, pre_env)]
        constraints.extend(
            post_env[name] == pre_env[name] for name in self.program_vars if name != assign.var_name
        )
        self.clauses.append(
            HornClause(
                head=post_rel(*post_state),
                body=[pre_rel(*pre_state), *constraints],
                description=f"Assign {assign.var_name}.",
            )
        )

    def encode_branch(self, if_node: If, pre_rel, post_rel):
        """Encode a conditional branch using split entry relations."""
        then_rel = self._relation("if_then")
        else_rel = self._relation("if_else")
        pre_state = self._fresh_state("if_state")
        pre_env = self._env(pre_state)
        cond = self._expr_to_z3(if_node.cond, pre_env)

        self.clauses.append(
            HornClause(
                head=then_rel(*pre_state),
                body=[pre_rel(*pre_state), cond],
                description="If-then branch gate.",
            )
        )
        self.clauses.append(
            HornClause(
                head=else_rel(*pre_state),
                body=[pre_rel(*pre_state), z3.Not(cond)],
                description="If-else branch gate.",
            )
        )
        self._encode_stmt(if_node.then_body, then_rel, post_rel)
        self._encode_stmt(if_node.else_body, else_rel, post_rel)

    def encode_loop(self, while_node: While, pre_rel, post_rel):
        """Encode an unbounded loop recursively or unroll it when bounded."""
        if while_node.bound is not None:
            self._encode_bounded_loop(while_node, pre_rel, post_rel)
            return

        loop_rel = self._relation("loop")
        self.loop_relations.append(loop_rel.name())
        self.loop_count += 1
        body_entry = self._relation("loop_body")
        body_exit = self._relation("loop_body_exit")

        entry_state = self._fresh_state("loop_entry")
        self.clauses.append(
            HornClause(
                head=loop_rel(*entry_state),
                body=[pre_rel(*entry_state)],
                description="Loop entry.",
            )
        )

        test_state = self._fresh_state("loop_test")
        test_env = self._env(test_state)
        cond = self._expr_to_z3(while_node.cond, test_env)
        self.clauses.append(
            HornClause(
                head=body_entry(*test_state),
                body=[loop_rel(*test_state), cond],
                description="Loop body when the guard holds.",
            )
        )
        self.clauses.append(
            HornClause(
                head=post_rel(*test_state),
                body=[loop_rel(*test_state), z3.Not(cond)],
                description="Loop exit when the guard fails.",
            )
        )

        self._encode_stmt(while_node.body, body_entry, body_exit)
        body_state = self._fresh_state("loop_back")
        self.clauses.append(
            HornClause(
                head=loop_rel(*body_state),
                body=[body_exit(*body_state)],
                description="Loop back-edge.",
            )
        )

    def encode_assertion(self, assert_node: Assert, pre_rel, post_rel=None):
        """Encode an assertion failure query and optional success passthrough."""
        pre_state = self._fresh_state("assert_state")
        pre_env = self._env(pre_state)
        cond = self._expr_to_z3(assert_node.cond, pre_env)
        self.clauses.append(
            HornClause(
                head=self.error_rel(),
                body=[pre_rel(*pre_state), z3.Not(cond)],
                description="Assertion violation reaches Error.",
            )
        )
        if post_rel is not None:
            self.clauses.append(
                HornClause(
                    head=post_rel(*pre_state),
                    body=[pre_rel(*pre_state), cond],
                    description="Assertion success preserves state.",
                )
            )

    def to_z3(self, program_vars=None):
        """Convert the encoded clauses into a Z3 Fixedpoint context."""
        if program_vars is not None:
            self.program_vars = list(program_vars)
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        fp.register_relation(*self.relations.values())
        fp.declare_var(*self._declared_vars.values())
        for clause in self.clauses:
            if clause.body:
                fp.rule(clause.head, clause.body)
            else:
                fp.rule(clause.head, z3.BoolVal(True))
        return fp, self.error_rel()

    def _encode_stmt(self, stmt, pre_rel, post_rel):
        if isinstance(stmt, Sequence):
            if not stmt.stmts:
                self._encode_skip(pre_rel, post_rel)
                return
            current_rel = pre_rel
            for index, nested in enumerate(stmt.stmts):
                target_rel = post_rel if index == len(stmt.stmts) - 1 else self._relation("seq")
                self._encode_stmt(nested, current_rel, target_rel)
                current_rel = target_rel
            return
        if isinstance(stmt, Assign):
            self.encode_assignment(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, If):
            self.encode_branch(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, While):
            self.encode_loop(stmt, pre_rel, post_rel)
            return
        if isinstance(stmt, Assert):
            self.encode_assertion(stmt, pre_rel, post_rel)
            return
        raise TypeError(f"Unsupported statement type: {type(stmt)!r}")

    def _encode_bounded_loop(self, while_node: While, pre_rel, post_rel):
        active_rel = pre_rel
        bound = while_node.bound or 0
        for _ in range(bound):
            body_rel = self._relation("bounded_loop_body")

