"""CEGAR-style counterexample analysis, validation, and minimization."""

from __future__ import annotations

from collections import deque
from dataclasses import dataclass, field
import itertools
from typing import Callable, Iterable

import z3


Predicate = z3.BoolRef
StateFormula = Callable[[list[z3.ExprRef]], z3.BoolRef]
TransitionFormula = Callable[[list[z3.ExprRef], list[z3.ExprRef]], z3.BoolRef]


@dataclass(frozen=True)
class State:
    values: dict


@dataclass(frozen=True)
class Transition:
    src: State
    dst: State
    action: str


@dataclass
class Counterexample:
    transitions: list[Transition]

    @property
    def length(self) -> int:
        return len(self.transitions)

    @property
    def states(self) -> list[State]:
        if not self.transitions:
            return []
        return [self.transitions[0].src] + [step.dst for step in self.transitions]

    def get_variable_trace(self, var_name: str) -> list[int]:
        return [state.values[var_name] for state in self.states if var_name in state.values]


@dataclass(frozen=True)
class ValidationResult:
    is_real: bool
    first_spurious_step: int | None
    reason: str = ""


@dataclass
class CEGARResult:
    safe: bool
    iterations: int
    predicates: list[Predicate]
    cex: Counterexample | None = None
    original_cex: Counterexample | None = None


@dataclass(frozen=True)
class TransitionSystemSpec:
    name: str
    variable_names: list[str]
    state_sorts: list[z3.SortRef]
    init_cond: StateFormula
    trans_rel: TransitionFormula
    safety: StateFormula
    max_depth: int = 20
    seed_predicates: list[Predicate] = field(default_factory=list)
    candidate_predicates: list[Predicate] = field(default_factory=list)
    inflate_real_cex: int = 0


def _fresh_state_vars(variable_names: list[str], suffix: str, state_sorts: list[z3.SortRef]):
    return [z3.Const(f"{name}_{suffix}", sort) for name, sort in zip(variable_names, state_sorts)]


def _value_to_z3(value):
    if isinstance(value, bool):
        return z3.BoolVal(value)
    return z3.IntVal(int(value))


def _state_equalities(state: State, variables: list[z3.ExprRef]) -> list[z3.BoolRef]:
    return [var == _value_to_z3(state.values[str(var).rsplit("_", 1)[0]]) for var in variables]


def _state_assignments(state: State, variable_names: list[str], variables: list[z3.ExprRef]) -> list[z3.BoolRef]:
    return [var == _value_to_z3(state.values[name]) for name, var in zip(variable_names, variables)]


def _eval_predicate(pred: Predicate, state: State, variable_names: list[str], canonical_vars: list[z3.ExprRef]) -> bool:
    substitutions = [(var, _value_to_z3(state.values[name])) for name, var in zip(variable_names, canonical_vars)]
    evaluated = z3.simplify(z3.substitute(pred, *substitutions))
    if z3.is_true(evaluated):
        return True
    if z3.is_false(evaluated):
        return False
    solver = z3.Solver()
    solver.add(evaluated)
    return solver.check() == z3.sat


class CEXValidator:
    """Concrete counterexample validator."""

    def __init__(self, variable_names: list[str], state_sorts: list[z3.SortRef]):
        self.variable_names = variable_names
        self.state_sorts = state_sorts

    def validate(self, cex, init_cond, trans_rel, safety) -> ValidationResult:
        if not cex.transitions:
            return ValidationResult(False, 0, "empty counterexample")

        initial_state = cex.transitions[0].src
        if not self._check_state_formula(initial_state, init_cond):
            return ValidationResult(False, 0, "initial state does not satisfy init")

        previous_dst = None
        for index, step in enumerate(cex.transitions):
            if previous_dst is not None and previous_dst.values != step.src.values:
                return ValidationResult(False, index, "trace is not continuous")
            if not self._check_transition(step.src, step.dst, trans_rel):
                return ValidationResult(False, index, "transition is not realizable")
            previous_dst = step.dst

        final_state = cex.transitions[-1].dst
        if self._check_state_formula(final_state, safety):
            return ValidationResult(False, len(cex.transitions), "final state does not violate safety")
        return ValidationResult(True, None, "")

    def _check_state_formula(self, state: State, formula: StateFormula) -> bool:
        variables = _fresh_state_vars(self.variable_names, "check", self.state_sorts)
        solver = z3.Solver()
        solver.add(_state_assignments(state, self.variable_names, variables))
        solver.add(formula(variables))
        return solver.check() == z3.sat

    def _check_transition(self, src: State, dst: State, trans_rel: TransitionFormula) -> bool:
        current_state = _fresh_state_vars(self.variable_names, "curr", self.state_sorts)
        next_state = _fresh_state_vars(self.variable_names, "next", self.state_sorts)
        solver = z3.Solver()
        solver.add(_state_assignments(src, self.variable_names, current_state))
        solver.add(_state_assignments(dst, self.variable_names, next_state))
        solver.add(trans_rel(current_state, next_state))
        return solver.check() == z3.sat


class AbstractDomain:
    """Predicate abstraction domain."""

    def __init__(self, variable_names: list[str], predicates: Iterable[Predicate] | None = None):
        self.variable_names = variable_names
        self.canonical_vars = [z3.Int(name) for name in variable_names]
        self.predicates: list[Predicate] = []
        for predicate in predicates or []:
            self.add_predicate(predicate)

    def abstract_state(self, concrete_state: State) -> tuple[bool, ...]:
        return tuple(
            _eval_predicate(predicate, concrete_state, self.variable_names, self.canonical_vars)
            for predicate in self.predicates
        )

    def is_subsumed(self, pred_new: Predicate, pred_existing: Predicate) -> bool:
        solver = z3.Solver()
        solver.add(pred_existing)
        solver.add(z3.Not(pred_new))
        return solver.check() == z3.unsat

    def add_predicate(self, pred: Predicate) -> bool:
        if any(self.is_subsumed(pred, existing) for existing in self.predicates):
            return False
        retained = [existing for existing in self.predicates if not self.is_subsumed(existing, pred)]
        retained.append(pred)
        self.predicates = retained
        return True

    @property
    def predicate_count(self) -> int:
        return len(self.predicates)


class PredicateRefiner:
    """Predicate refiner with a Craig-like SMT fallback when interpolation is unavailable."""

    def __init__(
        self,
        variable_names: list[str],
        init_cond: StateFormula | None = None,
        safety: StateFormula | None = None,
        candidate_pool: Iterable[Predicate] | None = None,
    ):
        self.variable_names = variable_names
        self.canonical_vars = [z3.Int(name) for name in variable_names]
        self.init_cond = init_cond
        self.safety = safety
        self.candidate_pool = list(candidate_pool or [])

    def extract_interpolants(self, cex, trans_rel) -> list[Predicate]:
        states = cex.states
        candidates = list(self.candidate_pool)
        candidates.extend(self._generic_candidates(states))
        interpolants: list[Predicate] = []
        for candidate in candidates:
            if self._separates_trace(candidate, states, trans_rel):
                interpolants.append(candidate)
            if len(interpolants) >= 3:
                break
        return interpolants

    def strengthen_invariant(self, current_preds, new_interpolants) -> list[Predicate]:
        domain = AbstractDomain(self.variable_names, current_preds)
        for predicate in new_interpolants:
            domain.add_predicate(predicate)
        return list(domain.predicates)

    def minimize_cex(self, cex, trans_rel) -> Counterexample:
        states = cex.states
        if len(states) < 3:
            return cex

        kept_indices = [0]
        current_index = 0
        while current_index < len(states) - 1:
            next_index = current_index + 1
            for candidate_index in range(len(states) - 1, current_index, -1):
                if self._transition_sat(states[current_index], states[candidate_index], trans_rel):
                    next_index = candidate_index
                    break
            kept_indices.append(next_index)
            current_index = next_index

        transitions = []
        for step_index, (src_index, dst_index) in enumerate(zip(kept_indices, kept_indices[1:])):
            transitions.append(
                Transition(
                    src=states[src_index],
                    dst=states[dst_index],
                    action=f"jump_{step_index}",
                )
            )
        return Counterexample(transitions)

    def _generic_candidates(self, states: list[State]) -> list[Predicate]:
        candidates: list[Predicate] = []
        if not states:
            return candidates
        seen = set()
        for state in states:
            for name, var in zip(self.variable_names, self.canonical_vars):
                value = int(state.values[name])
                for predicate in (
                    var == value,
                    var >= value,
                    var <= value,
                    var < value + 1,
                    var > value - 1,
                ):
                    key = predicate.sexpr()
                    if key not in seen:
                        seen.add(key)
                        candidates.append(predicate)
            for (name_a, var_a), (name_b, var_b) in itertools.combinations(
                zip(self.variable_names, self.canonical_vars), 2
            ):
                sum_value = int(state.values[name_a]) + int(state.values[name_b])
                diff_value = int(state.values[name_a]) - int(state.values[name_b])
                for predicate in (
                    var_a + var_b <= sum_value,
                    var_a + var_b >= sum_value,
                    var_a - var_b <= diff_value,
                    var_a - var_b >= diff_value,
                    var_a <= var_b,
                    var_a >= var_b,
                    var_a == var_b,
                ):
                    key = predicate.sexpr()
                    if key not in seen:
                        seen.add(key)
                        candidates.append(predicate)
        if self.safety is not None:
            safety_pred = self.safety(self.canonical_vars)
            if safety_pred.sexpr() not in seen:
                candidates.append(safety_pred)
        return candidates

    def _separates_trace(self, predicate: Predicate, states: list[State], trans_rel: TransitionFormula) -> bool:
        if not states:
            return False
        values = [
            _eval_predicate(predicate, state, self.variable_names, self.canonical_vars)
            for state in states
        ]
        if len(set(values)) == 1:
            return False

        for left, right in zip(states, states[1:]):
            left_value = _eval_predicate(predicate, left, self.variable_names, self.canonical_vars)
            right_value = _eval_predicate(predicate, right, self.variable_names, self.canonical_vars)
            if left_value and not right_value:
                if self._predicate_blocks_state(predicate, right):
                    return True
            if right_value and not left_value:
                if self._predicate_blocks_state(z3.Not(predicate), left):
                    return True
        if self.init_cond is not None and self._predicate_implied_by_init(predicate):
            return True
        return False

    def _predicate_blocks_state(self, predicate: Predicate, state: State) -> bool:
        solver = z3.Solver()
        solver.add(predicate)
        solver.add(
            _state_assignments(
                state,
                self.variable_names,
                self.canonical_vars,
            )
        )
        return solver.check() == z3.unsat

    def _predicate_implied_by_init(self, predicate: Predicate) -> bool:
        solver = z3.Solver()
        solver.add(self.init_cond(self.canonical_vars))
        solver.add(z3.Not(predicate))
        return solver.check() == z3.unsat

    def _transition_sat(self, src: State, dst: State, trans_rel: TransitionFormula) -> bool:
        current_state = _fresh_state_vars(self.variable_names, "min_curr", [z3.IntSort()] * len(self.variable_names))
        next_state = _fresh_state_vars(self.variable_names, "min_next", [z3.IntSort()] * len(self.variable_names))
        solver = z3.Solver()
        solver.add(_state_assignments(src, self.variable_names, current_state))
        solver.add(_state_assignments(dst, self.variable_names, next_state))
        solver.add(trans_rel(current_state, next_state))
        return solver.check() == z3.sat


class CEGARLoop:
    """Main CEGAR loop driven by predicate abstraction and Spacer checks."""

    def __init__(
        self,
        init_cond,
        trans_rel,
        safety,
        max_iterations=20,
        predicate_budget=50,
        *,
        variable_names: list[str] | None = None,
        state_sorts: list[z3.SortRef] | None = None,
        max_depth: int = 20,
        seed_predicates: Iterable[Predicate] | None = None,
        candidate_predicates: Iterable[Predicate] | None = None,
        name: str = "cegar",
        inflate_real_cex: int = 0,
    ):
        self.init_cond = init_cond
        self.trans_rel = trans_rel
        self.safety = safety
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.variable_names = list(variable_names or ["x"])
        self.state_sorts = list(state_sorts or [z3.IntSort()] * len(self.variable_names))
        self.max_depth = max_depth
        self.name = name
        self.inflate_real_cex = inflate_real_cex
        self.seed_predicates = list(seed_predicates or [])

        self.domain = AbstractDomain(self.variable_names, self.seed_predicates)
        self.validator = CEXValidator(self.variable_names, self.state_sorts)
        self.refiner = PredicateRefiner(
            self.variable_names,
            init_cond=self.init_cond,
            safety=self.safety,
            candidate_pool=candidate_predicates,
        )

    def run(self) -> CEGARResult:
        for iteration in range(1, self.max_iterations + 1):
            abstract_result = self._verify_abstraction()
            if abstract_result["safe"]:
                return CEGARResult(True, iteration, list(self.domain.predicates), None, None)

            real_cex = self._find_concrete_cex(self.max_depth)
            if real_cex is not None:
                inflated = self._inflate_counterexample(real_cex)
                validation = self.validator.validate(inflated, self.init_cond, self.trans_rel, self.safety)
                if validation.is_real:
                    minimized = self.refiner.minimize_cex(inflated, self.trans_rel)
                    return CEGARResult(
                        False,
                        iteration,
                        list(self.domain.predicates),
                        minimized,
                        inflated,
                    )

            abstract_cex = self._materialize_abstract_cex(abstract_result["path"])
            validation = self.validator.validate(abstract_cex, self.init_cond, self.trans_rel, self.safety)
            if validation.is_real:
                minimized = self.refiner.minimize_cex(abstract_cex, self.trans_rel)
                return CEGARResult(
                    False,
                    iteration,
                    list(self.domain.predicates),
                    minimized,
                    abstract_cex,
                )

            new_preds = self.refiner.extract_interpolants(abstract_cex, self.trans_rel)
            before = self.domain.predicate_count
            self.domain.predicates = self.refiner.strengthen_invariant(self.domain.predicates, new_preds)
            if self.domain.predicate_count == before or self.domain.predicate_count >= self.predicate_budget:
                break

        return CEGARResult(True, self.max_iterations, list(self.domain.predicates), None, None)

    def _verify_abstraction(self) -> dict:
        valuations = list(self._enumerate_valuations())
        init_vals = [valuation for valuation in valuations if self._valuation_sat(valuation, mode="init")]
        error_vals = [valuation for valuation in valuations if self._valuation_sat(valuation, mode="error")]
        edges = {
            (src, dst): self._transition_between_valuations(src, dst)
            for src in valuations
            for dst in valuations
        }

        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        inv = self._abstract_relation("abs_inv")
        error = z3.Function(f"{self.name}_abs_error", z3.BoolSort())
        fp.register_relation(inv, error)

        for valuation in init_vals:
            fp.rule(self._abstract_call(inv, valuation), z3.BoolVal(True))
        for (src, dst), enabled in edges.items():
            if enabled:
                fp.rule(self._abstract_call(inv, dst), [self._abstract_call(inv, src)])
        for valuation in error_vals:
            fp.rule(error(), [self._abstract_call(inv, valuation)])

        result = fp.query(error())
        path = self._abstract_path(init_vals, error_vals, edges)
        return {"safe": result == z3.unsat or path is None, "path": path, "answer": str(fp.get_answer())}

    def _find_concrete_cex(self, max_depth: int) -> Counterexample | None:
        for depth in range(max_depth + 1):
            state_layers = [
                _fresh_state_vars(self.variable_names, f"bmc_{index}", self.state_sorts)
                for index in range(depth + 1)
            ]
            solver = z3.Solver()
            solver.add(self.init_cond(state_layers[0]))
            for index in range(depth):
                solver.add(self.trans_rel(state_layers[index], state_layers[index + 1]))
            solver.add(z3.Not(self.safety(state_layers[-1])))
            if solver.check() != z3.sat:
                continue
            model = solver.model()
            states = [self._model_state(model, layer) for layer in state_layers]
            transitions = [
                Transition(states[index], states[index + 1], f"step_{index}")
                for index in range(len(states) - 1)
            ]
            return Counterexample(transitions)
        return None

    def _inflate_counterexample(self, cex: Counterexample) -> Counterexample:
        if self.inflate_real_cex <= 0 or not cex.transitions:
            return cex
        transitions = list(cex.transitions)
        insertion_state = transitions[0].src
        for index in range(self.inflate_real_cex):
            if not self._transition_sat(insertion_state, insertion_state):
                break
            transitions.insert(index, Transition(insertion_state, insertion_state, f"stutter_{index}"))
        return Counterexample(transitions)

    def _materialize_abstract_cex(self, path: list[tuple[bool, ...]] | None) -> Counterexample:
        if not path:
            init_state = self._solve_state(self.init_cond)
            unsafe_state = self._solve_state(lambda state: z3.Not(self.safety(state)))
            if init_state is None or unsafe_state is None:
                return Counterexample([])
            return Counterexample([Transition(init_state, unsafe_state, "abstract_error")])

        current_state = self._solve_state(lambda state: z3.And(self.init_cond(state), self._valuation_formula(path[0], state)))
        if current_state is None:
            current_state = self._solve_state(self.init_cond)
        if current_state is None:
            return Counterexample([])

        transitions: list[Transition] = []
        for index, valuation in enumerate(path[1:], start=1):
            require_unsafe = index == len(path) - 1
            dst_state = self._solve_next_state(current_state, valuation, require_unsafe=require_unsafe)
            action = f"abstract_step_{index - 1}"
            if dst_state is None:
                dst_state = self._solve_state(
                    lambda state, valuation=valuation, require_unsafe=require_unsafe: z3.And(
                        self._valuation_formula(valuation, state),
                        z3.Not(self.safety(state)) if require_unsafe else z3.BoolVal(True),
                    )
                )
                action = f"spurious_step_{index - 1}"
            if dst_state is None:
                dst_state = current_state
            transitions.append(Transition(current_state, dst_state, action))
            current_state = dst_state

        if not transitions:
            unsafe_state = self._solve_state(lambda state: z3.Not(self.safety(state)))
            if unsafe_state is not None:
                transitions.append(Transition(current_state, unsafe_state, "abstract_error"))
        elif self._state_satisfies(current_state, self.safety):
            unsafe_state = self._solve_state(lambda state: z3.Not(self.safety(state)))
            if unsafe_state is not None:
                transitions.append(Transition(current_state, unsafe_state, "abstract_error"))
        return Counterexample(transitions)

    def _enumerate_valuations(self):
        predicate_count = self.domain.predicate_count
        if predicate_count == 0:
            yield ()
            return
        yield from itertools.product([False, True], repeat=predicate_count)

    def _valuation_formula(self, valuation: tuple[bool, ...], variables: list[z3.ExprRef]) -> z3.BoolRef:
        conjuncts = []
        for predicate, bit in zip(self.domain.predicates, valuation):
            substitutions = [(z3.Int(name), var) for name, var in zip(self.variable_names, variables)]
            instance = z3.substitute(predicate, *substitutions)
            conjuncts.append(instance if bit else z3.Not(instance))
        return z3.And(conjuncts) if conjuncts else z3.BoolVal(True)

    def _valuation_sat(self, valuation: tuple[bool, ...], *, mode: str) -> bool:
        variables = _fresh_state_vars(self.variable_names, f"abs_{mode}", self.state_sorts)
        solver = z3.Solver()
        solver.add(self._valuation_formula(valuation, variables))
        if mode == "init":
            solver.add(self.init_cond(variables))
        elif mode == "error":
            solver.add(z3.Not(self.safety(variables)))
        else:
            raise ValueError(f"unknown valuation mode: {mode}")
        return solver.check() == z3.sat

    def _transition_between_valuations(self, src: tuple[bool, ...], dst: tuple[bool, ...]) -> bool:
        current_state = _fresh_state_vars(self.variable_names, "abs_curr", self.state_sorts)
        next_state = _fresh_state_vars(self.variable_names, "abs_next", self.state_sorts)
        solver = z3.Solver()
        solver.add(self._valuation_formula(src, current_state))
        solver.add(self.trans_rel(current_state, next_state))
        solver.add(self._valuation_formula(dst, next_state))
        return solver.check() == z3.sat

    def _abstract_relation(self, name: str):
        if self.domain.predicate_count == 0:
            return z3.Function(f"{self.name}_{name}", z3.BoolSort())
        return z3.Function(
            f"{self.name}_{name}",
            *([z3.BoolSort()] * self.domain.predicate_count),
            z3.BoolSort(),
        )

    def _abstract_call(self, relation, valuation: tuple[bool, ...]):
        if not valuation:
            return relation()
        return relation(*[z3.BoolVal(bit) for bit in valuation])

    def _abstract_path(self, init_vals, error_vals, edges):
        if not init_vals:
            return None
        queue = deque(init_vals)
        parents = {valuation: None for valuation in init_vals}
        while queue:
            current = queue.popleft()
            if current in error_vals:
                path = [current]
                while parents[path[-1]] is not None:
                    path.append(parents[path[-1]])
                return list(reversed(path))
            for target in (valuation for valuation in parents.keys() | set()):  # pragma: no cover - placeholder
                pass
        all_valuations = sorted({src for src, _ in edges} | {dst for _, dst in edges}, key=str)
        for current in list(parents):
            queue.appendleft(current)
        queue = deque(init_vals)
        while queue:
            current = queue.popleft()
            if current in error_vals:
                path = [current]
                while parents[path[-1]] is not None:
                    path.append(parents[path[-1]])
                return list(reversed(path))
            for nxt in all_valuations:
                if not edges.get((current, nxt), False) or nxt in parents:
                    continue
                parents[nxt] = current
                queue.append(nxt)
        return None

    def _solve_state(self, formula_builder: Callable[[list[z3.ExprRef]], z3.BoolRef]) -> State | None:
        variables = _fresh_state_vars(self.variable_names, "solve", self.state_sorts)
        solver = z3.Solver()
        solver.add(formula_builder(variables))
        if solver.check() != z3.sat:
            return None
        return self._model_state(solver.model(), variables)

    def _solve_next_state(self, current_state: State, valuation: tuple[bool, ...], *, require_unsafe: bool) -> State | None:
        current_vars = _fresh_state_vars(self.variable_names, "solve_curr", self.state_sorts)
        next_vars = _fresh_state_vars(self.variable_names, "solve_next", self.state_sorts)
        solver = z3.Solver()
        solver.add(_state_assignments(current_state, self.variable_names, current_vars))
        solver.add(self.trans_rel(current_vars, next_vars))
        solver.add(self._valuation_formula(valuation, next_vars))
        if require_unsafe:
            solver.add(z3.Not(self.safety(next_vars)))
        if solver.check() != z3.sat:
            return None
        return self._model_state(solver.model(), next_vars)

    def _model_state(self, model: z3.ModelRef, variables: list[z3.ExprRef]) -> State:
        values = {}
        for name, variable in zip(self.variable_names, variables):
            value = model.eval(variable, model_completion=True)
            if z3.is_true(value) or z3.is_false(value):
                values[name] = z3.is_true(value)
            else:
                values[name] = value.as_long()
        return State(values)

    def _state_satisfies(self, state: State, formula: StateFormula) -> bool:
        variables = _fresh_state_vars(self.variable_names, "sat", self.state_sorts)
        solver = z3.Solver()
        solver.add(_state_assignments(state, self.variable_names, variables))
        solver.add(formula(variables))
        return solver.check() == z3.sat

    def _transition_sat(self, src: State, dst: State) -> bool:
        current_state = _fresh_state_vars(self.variable_names, "inflate_curr", self.state_sorts)
        next_state = _fresh_state_vars(self.variable_names, "inflate_next", self.state_sorts)
        solver = z3.Solver()
        solver.add(_state_assignments(src, self.variable_names, current_state))
        solver.add(_state_assignments(dst, self.variable_names, next_state))
        solver.add(self.trans_rel(current_state, next_state))
        return solver.check() == z3.sat


