"""Experiments for the CEGAR counterexample minimization layer."""

from __future__ import annotations

import z3

from framework import report_result
from verification.cex_minimizer import CEGARLoop, TransitionSystemSpec


def _vars(*names):
    return [z3.Int(name) for name in names]


def _counter_safe_after_refinement() -> TransitionSystemSpec:
    x = _vars("x")[0]

    def init(state):
        (sx,) = state
        return sx == 0

    def trans(state, next_state):
        (sx,) = state
        (nx,) = next_state
        return z3.Or(z3.And(sx < 10, nx == sx + 1), z3.And(sx >= 10, nx == sx))

    def safety(state):
        (sx,) = state
        return sx <= 10

    return TransitionSystemSpec(
        name="counter_refine",
        variable_names=["x"],
        state_sorts=[z3.IntSort()],
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        max_depth=15,
        candidate_predicates=[x <= 10],
    )


def _double_counter_unsafe() -> TransitionSystemSpec:
    x, y = _vars("x", "y")

    def init(state):
        sx, sy = state
        return z3.And(sx == 0, sy == 0)

    def trans(state, next_state):
        sx, sy = state
        nx, ny = next_state
        return z3.And(nx == sx + 1, ny == sy + 2)

    def safety(state):
        sx, sy = state
        return sx + sy < 50

    return TransitionSystemSpec(
        name="double_counter",
        variable_names=["x", "y"],
        state_sorts=[z3.IntSort(), z3.IntSort()],
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        max_depth=20,
        candidate_predicates=[x >= 0, y >= 0, x + y < 50],
    )


def _array_bounds_safe() -> TransitionSystemSpec:
    i, limit = _vars("i", "limit")

    def init(state):
        si, slimit = state
        return z3.And(si == 0, slimit == 3)

    def trans(state, next_state):
        si, slimit = state
        ni, nlimit = next_state
        return z3.Or(
            z3.And(si < slimit, ni == si + 1, nlimit == slimit),
            z3.And(si >= slimit, ni == si, nlimit == slimit),
        )

    def safety(state):
        si, slimit = state
        return z3.And(si >= 0, si <= slimit, slimit == 3)

    return TransitionSystemSpec(
        name="array_bounds",
        variable_names=["i", "limit"],
        state_sorts=[z3.IntSort(), z3.IntSort()],
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        max_depth=10,
        candidate_predicates=[i >= 0, limit == 3, i <= limit],
    )


def _nonnegative_loop_safe() -> TransitionSystemSpec:
    x = _vars("x")[0]

    def init(state):
        (sx,) = state
        return sx == 0

    def trans(state, next_state):
        (sx,) = state
        (nx,) = next_state
        return z3.Or(z3.And(sx < 5, nx == sx + 1), z3.And(sx >= 5, nx == sx))

    def safety(state):
        (sx,) = state
        return sx >= 0

    return TransitionSystemSpec(
        name="nonnegative_loop",
        variable_names=["x"],
        state_sorts=[z3.IntSort()],
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        max_depth=10,
        seed_predicates=[x >= 0],
        candidate_predicates=[x >= 0],
    )


def _producer_consumer_unsafe() -> TransitionSystemSpec:
    produced, consumed, buf = _vars("produced", "consumed", "buf")

    def init(state):
        sp, sc, sb = state
        return z3.And(sp == 0, sc == 0, sb == 0)

    def trans(state, next_state):
        sp, sc, sb = state
        np, nc, nb = next_state
        produce = z3.And(sp < 4, np == sp + 1, nc == sc, nb == sb + 1)
        consume = z3.And(sb > 0, np == sp, nc == sc + 1, nb == sb - 1)
        stutter = z3.And(np == sp, nc == sc, nb == sb)
        return z3.Or(produce, consume, stutter)

    def safety(state):
        _sp, _sc, sb = state
        return sb <= 2

    return TransitionSystemSpec(
        name="producer_consumer",
        variable_names=["produced", "consumed", "buf"],
        state_sorts=[z3.IntSort(), z3.IntSort(), z3.IntSort()],
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        max_depth=6,
        inflate_real_cex=2,
        candidate_predicates=[buf <= 2, produced >= consumed, buf >= 0],
    )


SYSTEMS = [
    _counter_safe_after_refinement(),
    _double_counter_unsafe(),
    _array_bounds_safe(),
    _nonnegative_loop_safe(),
    _producer_consumer_unsafe(),
]


def run_cegar_experiments():
    """Run the seeded CEGAR benchmarks and report aggregate metrics."""
    results = []
    for system in SYSTEMS:
        loop = CEGARLoop(
            system.init_cond,
            system.trans_rel,
            system.safety,
            max_iterations=20,
            predicate_budget=50,
            variable_names=system.variable_names,
            state_sorts=system.state_sorts,
            max_depth=system.max_depth,
            seed_predicates=system.seed_predicates,
            candidate_predicates=system.candidate_predicates,
            name=system.name,
            inflate_real_cex=system.inflate_real_cex,
        )
        results.append((system, loop.run()))

    metrics = {
        "CEGAR_ITERATIONS": sum(result.iterations for _, result in results),
        "CEGAR_PREDICATES_ADDED": sum(
            max(0, len(result.predicates) - len(system.seed_predicates))
            for system, result in results
        ),
        "CEGAR_CEX_LENGTH_ORIGINAL": sum(
            result.original_cex.length
            for _system, result in results
            if not result.safe and result.original_cex is not None
        ),
        "CEGAR_CEX_LENGTH_MINIMIZED": sum(
            result.cex.length for _system, result in results if not result.safe and result.cex is not None
        ),
        "CEGAR_VERIFIED_SAFE": sum(1 for _system, result in results if result.safe),
    }
    for key, value in metrics.items():
        report_result(key, value)
    return metrics


if __name__ == "__main__":
    run_cegar_experiments()

