"""Counterexample validation, minimization, and predicate-refinement utilities."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from itertools import product
from typing import Callable, Iterable, Sequence

import z3


@dataclass(frozen=True)
class State:
    """Concrete program state."""

    values: dict[str, int]

    def with_updates(self, **updates: int) -> "State":
        next_values = dict(self.values)
        next_values.update(updates)
        return State(next_values)

    def key(self, var_names: Sequence[str]) -> tuple[int, ...]:
        return tuple(self.values[name] for name in var_names)


@dataclass(frozen=True)
class Transition:
    """Concrete state transition."""

    src: State
    dst: State
    action: str


@dataclass(frozen=True)
class Counterexample:
    """Concrete or abstractly reconstructed counterexample trace."""

    transitions: list[Transition]
    initial_state: State | None = None

    @property
    def length(self) -> int:
        return len(self.transitions)

    def states(self) -> list[State]:
        if self.transitions:
            return [self.transitions[0].src] + [transition.dst for transition in self.transitions]
        if self.initial_state is not None:
            return [self.initial_state]
        return []

    def get_variable_trace(self, var_name: str) -> list[int]:
        return [state.values[var_name] for state in self.states() if var_name in state.values]


@dataclass(frozen=True)
class ValidationResult:
    is_real: bool
    first_spurious_step: int | None


@dataclass(frozen=True)
class CEGARResult:
    safe: bool
    iterations: int
    predicates: list[z3.ExprRef]
    cex: Counterexample | None = None
    original_cex: Counterexample | None = None


@dataclass(frozen=True)
class AbstractGraph:
    members: dict[int, list[State]]
    edges: dict[int, list[int]]
    edge_representatives: dict[tuple[int, int], Transition]
    init_ids: list[int]
    unsafe_ids: set[int]
    unsafe_representatives: dict[int, State]


@dataclass
class FiniteStateSystem:
