    init_cond: Callable[[State], bool]
    trans_rel: Callable[[State, State], bool]
    safety: Callable[[State], bool]
    initial_predicates: list[z3.ExprRef] = field(default_factory=list)
    candidate_predicates: list[z3.ExprRef] = field(default_factory=list)

    def enumerate_states(self) -> list[State]:
        domain_values = [self.domains[name] for name in self.var_names]
        return [State(dict(zip(self.var_names, values))) for values in product(*domain_values)]

    def successors(self, state: State) -> list[Transition]:
        return self.successor_fn(state)


def _attach_symbolic(concrete_fn, symbolic_fn, system: FiniteStateSystem):
    setattr(concrete_fn, "_symbolic", symbolic_fn)
    setattr(concrete_fn, "_system", system)
    return concrete_fn


def _state_env(var_names: Sequence[str], suffix: str) -> dict[str, z3.IntNumRef]:
    return {name: z3.Int(f"{name}_{suffix}") for name in var_names}


def _substitute_state(predicate: z3.ExprRef, state: State) -> z3.ExprRef:
    substitutions = [(z3.Int(name), z3.IntVal(value)) for name, value in state.values.items()]
    return z3.simplify(z3.substitute(predicate, *substitutions))


def _eval_predicate(predicate: z3.ExprRef, state: State) -> bool:
    result = _substitute_state(predicate, state)
    if z3.is_true(result):
        return True
    if z3.is_false(result):
        return False
    solver = z3.Solver()
    solver.add(z3.Not(result))
    return solver.check() == z3.unsat


def _call_unary(predicate, state: State) -> bool:
    symbolic = getattr(predicate, "_symbolic", None)
    if symbolic is not None:
        solver = z3.Solver()
        env = _state_env(sorted(state.values), "cur")
        solver.add(symbolic(env))
        for name, value in state.values.items():
            solver.add(env[name] == value)
        return solver.check() == z3.sat
    return bool(predicate(state))


def _call_binary(relation, src: State, dst: State) -> bool:
    symbolic = getattr(relation, "_symbolic", None)
    if symbolic is not None:
        solver = z3.Solver()
        current_env = _state_env(sorted(src.values), "cur")
        next_env = _state_env(sorted(dst.values), "nxt")
        solver.add(symbolic(current_env, next_env))
        for name, value in src.values.items():
            solver.add(current_env[name] == value)
        for name, value in dst.values.items():
            solver.add(next_env[name] == value)
        return solver.check() == z3.sat
    return bool(relation(src, dst))


def _dedupe_exprs(predicates: Iterable[z3.ExprRef]) -> list[z3.ExprRef]:
    seen: set[str] = set()
    deduped: list[z3.ExprRef] = []
    for predicate in predicates:
        key = str(z3.simplify(predicate))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(z3.simplify(predicate))
    return deduped


class CEXValidator:
    """Validate whether a counterexample is real under concrete semantics."""

    def validate(self, cex, init_cond, trans_rel, safety) -> ValidationResult:
        states = cex.states()
        if not states:
            return ValidationResult(False, 0)
        if not _call_unary(init_cond, states[0]):
            return ValidationResult(False, 0)
        for index, transition in enumerate(cex.transitions):
            if index > 0 and transition.src.values != cex.transitions[index - 1].dst.values:
                return ValidationResult(False, index)
            if not _call_binary(trans_rel, transition.src, transition.dst):
                return ValidationResult(False, index)
        if _call_unary(safety, states[-1]):
            return ValidationResult(False, len(cex.transitions))
        return ValidationResult(True, None)


class AbstractDomain:
    """Predicate abstraction domain."""

    def __init__(self, var_names: Sequence[str], predicates: Sequence[z3.ExprRef] | None = None):
        self.var_names = list(var_names)
        self.predicates: list[z3.ExprRef] = []
        for predicate in predicates or []:
            self.add_predicate(predicate)

    def abstract_state(self, concrete_state: State) -> tuple[bool, ...]:
        return tuple(_eval_predicate(predicate, concrete_state) for predicate in self.predicates)

    def _implies(self, left: z3.ExprRef, right: z3.ExprRef) -> bool:
        solver = z3.Solver()
        solver.add(left, z3.Not(right))
        return solver.check() == z3.unsat

    def is_subsumed(self, pred_new: z3.ExprRef, pred_existing: z3.ExprRef) -> bool:
        return self._implies(pred_existing, pred_new)

    def add_predicate(self, pred: z3.ExprRef) -> bool:
        predicate = z3.simplify(pred)
        for existing in self.predicates:
            if self.is_subsumed(predicate, existing):
                return False
        self.predicates = [
            existing for existing in self.predicates if not self._implies(predicate, existing)
        ]
        self.predicates.append(predicate)
        return True

    @property
    def predicate_count(self) -> int:
        return len(self.predicates)


class PredicateRefiner:
    """Interpolation-style predicate refiner with a heuristic fallback."""

    def __init__(
        self,
        var_names: Sequence[str],
        candidate_pool: Sequence[z3.ExprRef] | None = None,
        safety=None,
    ) -> None:
        self.var_names = list(var_names)
        self.candidate_pool = list(candidate_pool or [])
        self.safety = safety

    def _separating_candidates(self, left: State, right: State) -> list[z3.ExprRef]:
        candidates: list[z3.ExprRef] = []
        for name in self.var_names:
            left_value = left.values[name]
            right_value = right.values[name]
            var = z3.Int(name)
            if left_value == right_value:
                continue
            candidates.append(var == left_value)
            candidates.append(var == right_value)
            if left_value < right_value:
                candidates.append(var <= left_value)
                candidates.append(var >= right_value)
            else:
                candidates.append(var >= left_value)
                candidates.append(var <= right_value)
        for index, first in enumerate(self.var_names):
            for second in self.var_names[index + 1 :]:
                left_delta = left.values[first] - left.values[second]
                right_delta = right.values[first] - right.values[second]
                if left_delta == right_delta:
                    continue
                expr = z3.Int(first) - z3.Int(second)
                candidates.append(expr == left_delta)
                candidates.append(expr == right_delta)
        return candidates

    def extract_interpolants(self, cex, trans_rel) -> list[z3.ExprRef]:
        """Return separating predicates for a spurious counterexample.

        This Z3 build does not expose the interpolation API, so the implementation
        falls back to predicates that separate the inconsistent states responsible
        for the spurious trace.
        """

        states = cex.states()
        candidates: list[z3.ExprRef] = []

        if len(states) <= 1:
            candidates.extend(self.candidate_pool)
            if states:
                candidates.extend(z3.Int(name) == states[0].values[name] for name in self.var_names)
            return _dedupe_exprs(candidates)

        previous_dst = None
        for index, transition in enumerate(cex.transitions):
            if index > 0 and previous_dst is not None and transition.src.values != previous_dst.values:
                candidates.extend(self._separating_candidates(previous_dst, transition.src))
                break
            if not _call_binary(trans_rel, transition.src, transition.dst):
                candidates.extend(self._separating_candidates(transition.src, transition.dst))
                break
            previous_dst = transition.dst

        if self.safety is not None and _call_unary(self.safety, states[-1]):
            candidates.extend(self._separating_candidates(states[-2], states[-1]))

        if self.candidate_pool:
            if len(states) > 1:
                left = states[0]
                right = states[-1]
                candidates = [
                    predicate
                    for predicate in self.candidate_pool
                    if _eval_predicate(predicate, left) != _eval_predicate(predicate, right)
                ] + candidates
            else:
                candidates = list(self.candidate_pool) + candidates

        if not candidates:
            candidates.extend(z3.Int(name) == states[-1].values[name] for name in self.var_names)
        return _dedupe_exprs(candidates)

    def strengthen_invariant(
        self, current_preds: Sequence[z3.ExprRef], new_interpolants: Sequence[z3.ExprRef]
    ) -> list[z3.ExprRef]:
        domain = AbstractDomain(self.var_names, current_preds)
        for predicate in new_interpolants:
            domain.add_predicate(predicate)
        return list(domain.predicates)

